"""Check the public slugify contract with standard-library unittest.

Responsibility: test observable slug output and invalid input without services.
Assumption: NFKD removes accents from Latin letters; remaining non-ASCII
characters are discarded rather than transliterated.
AI assistance: this test file was drafted with AI assistance.
Copyright: rights remain with the project's copyright holder.
"""

import unittest

from slug import slugify


class SlugifyTests(unittest.TestCase):
    def test_ordinary_words_and_case(self):
        for text, expected in (
            ("hello", "hello"),
            ("HELLO", "hello"),
            ("Hello, World!", "hello-world"),
            ("MiXeD Case 123", "mixed-case-123"),
        ):
            with self.subTest(text=text):
                self.assertEqual(slugify(text), expected)

    def test_separator_runs_and_edge_trimming(self):
        for text, expected in (
            ("  alpha\t\nbeta  ", "alpha-beta"),
            ("one___two...three", "one-two-three"),
            ("---Hello, _ World!! ---", "hello-world"),
        ):
            with self.subTest(text=text):
                self.assertEqual(slugify(text), expected)

    def test_accented_latin_letters(self):
        for text, expected in (
            ("  Café_and TEA  ", "cafe-and-tea"),
            ("Crème brûlée", "creme-brulee"),
            ("Cafe\u0301", "cafe"),
        ):
            with self.subTest(text=text):
                self.assertEqual(slugify(text), expected)

    def test_empty_and_all_discarded_input(self):
        for text in ("", "---", "\t!_\n", "中文😀"):
            with self.subTest(text=text):
                self.assertEqual(slugify(text), "")

    def test_non_string_input_raises_type_error(self):
        for value in (None, 42, b"hello", ["hello"]):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    slugify(value)


if __name__ == "__main__":
    unittest.main()

